import { kv } from "@vercel/kv";
import { randomBytes, webcrypto, createHash } from "crypto";

// ---- Device-bound session check (identical copy lives in webauthn.js,
// dashboard.js, chat-config.js and knowledge-base.js) --------------------
// A session token alone is NOT enough. At sign-in the browser creates a
// non-extractable signing key and registers its public half with the
// session; every request must carry a fresh one-time signature:
//   X-Dashboard-Proof: <timestamp-ms>.<nonce>.<signature, base64url>
//   signature = ECDSA-P256-SHA256 over:
//     METHOD \n /path?query \n timestamp \n nonce \n sha256(token)
// A copied token is useless without the original browser's key.
const MAX_SKEW_MS = 60 * 1000;
const NONCE_TTL_SECONDS = 180;

const b64urlToBuf = (s) => Buffer.from(String(s).replace(/-/g, "+").replace(/_/g, "/"), "base64");

function isValidPublicJwk(jwk) {
  return Boolean(
    jwk &&
      typeof jwk === "object" &&
      jwk.kty === "EC" &&
      jwk.crv === "P-256" &&
      typeof jwk.x === "string" && jwk.x.length <= 100 &&
      typeof jwk.y === "string" && jwk.y.length <= 100 &&
      jwk.d === undefined
  );
}

// Verifies the proof for `token`. Returns true/false, never throws.
async function verifyProofCore(req, token) {
  try {
    if (typeof token !== "string" || token.length < 20 || token.length > 100) return false;

    const raw = await kv.get(`webauthn_session_${token}`);
    if (!raw) { req._why = "no-session"; return false; }
    const record = typeof raw === "string" ? JSON.parse(raw) : raw;
    if (!record || !isValidPublicJwk(record.pk)) { req._why = "unbound-session"; return false; } // old/unbound sessions are refused

    const header = req.headers["x-dashboard-proof"];
    if (typeof header !== "string" || header.length > 400) { req._why = "no-proof"; return false; }
    const [ts, nonce, sig] = header.split(".");
    if (!ts || !nonce || !sig || nonce.length < 16 || nonce.length > 64) return false;

    const tsNum = Number(ts);
    if (!Number.isFinite(tsNum) || Math.abs(Date.now() - tsNum) > MAX_SKEW_MS) { req._why = "clock-skew"; return false; }

    const tokenHash = createHash("sha256").update(token).digest("hex");
    const message = `${req.method}\n${req.url}\n${ts}\n${nonce}\n${tokenHash}`;

    const key = await webcrypto.subtle.importKey(
      "jwk",
      { kty: "EC", crv: "P-256", x: record.pk.x, y: record.pk.y, ext: true },
      { name: "ECDSA", namedCurve: "P-256" },
      false,
      ["verify"]
    );

    const ok = await webcrypto.subtle.verify(
      { name: "ECDSA", hash: "SHA-256" },
      key,
      b64urlToBuf(sig),
      new TextEncoder().encode(message)
    );
    if (!ok) { req._why = "bad-signature"; return false; }

    // One-time use: reject if this nonce was already seen.
    const fresh = await kv.set(`proof_nonce_${tokenHash.slice(0, 16)}_${nonce}`, "1", {
      nx: true,
      ex: NONCE_TTL_SECONDS
    });
    if (!(fresh === "OK" || fresh === true)) { req._why = "replay"; return false; }
    return true;
  } catch (err) {
    console.error("Session proof check failed:", err);
    return false;
  }
}


// ---- Roles --------------------------------------------------------------
// Every sign-in carries the role of the passkey that was used (ADMIN,
// RESTRICTED, READ_ONLY). The role is looked up again on every request, so
// removing a user or changing their role takes effect immediately.
const ROLE_RANK = { READ_ONLY: 1, RESTRICTED: 2, ADMIN: 3 };

async function verifyProof(req, token) {
  if (!(await verifyProofCore(req, token))) return false;
  try {
    const rawSession = await kv.get(`webauthn_session_${token}`);
    const session = rawSession ? (typeof rawSession === "string" ? JSON.parse(rawSession) : rawSession) : null;
    const rawCreds = await kv.get("webauthn_credentials");
    const creds = rawCreds ? (typeof rawCreds === "string" ? JSON.parse(rawCreds) : rawCreds) : [];
    const cred = session && session.cid && Array.isArray(creds) ? creds.find((c) => c.id === session.cid) : null;
    if (!cred) { req._why = "revoked"; return false; }
    req._role = ROLE_RANK[cred.role] ? cred.role : "ADMIN"; // passkeys from before roles existed are the owner's
    req._who = String(cred.label || "");
    req._cid = cred.id;
    return true;
  } catch (err) {
    console.error("Role lookup failed:", err);
    return false;
  }
}

// Drop-in replacement for each endpoint's old requireSession().
// Sends the 401 itself and returns null on failure; returns the token on success.
async function requireSession(req, res, minRole = "READ_ONLY") {
  const token = req.headers.authorization?.replace("Bearer ", "");

  if (!token) {
    res.status(401).json({ error: "Not signed in." });
    return null;
  }

  if (!(await verifyProof(req, token))) {
    res.status(401).json({ error: "Session expired. Please sign in again.", reason: req._why || "invalid" });
    return null;
  }

  if ((ROLE_RANK[req._role] || 0) < (ROLE_RANK[minRole] || 99)) {
    res.status(403).json({ error: "Your role does not allow this action.", reason: "role" });
    return null;
  }

  return token;
}


const KEYS = {
  conversation: "tyler_ai_conversations",
  resume: "tyler_ai_resume_requests",
  callRequest: "tyler_ai_call_requests",
  intake: "visitor_intake_log"
};

function parseEntries(entries) {
  return (entries || []).map((entry) => {
    try {
      return typeof entry === "string" ? JSON.parse(entry) : entry;
    } catch {
      return { raw: entry };
    }
  });
}

async function handleData(req, res) {
  if (!(await requireSession(req, res))) return;

  try {
    const [rawConversations, rawResumeRequests, rawMaintenanceLog, rawFlagged, bannedIps, bannedRanges, bannedFingerprints, rawInjectionAttempts, rawCallRequests, rawIntakeLog, rawA11yIssues, rawGreetLinks] = await Promise.all([
      kv.lrange("tyler_ai_conversations", 0, 199),
      kv.lrange("tyler_ai_resume_requests", 0, 199),
      kv.lrange("site_maintenance_log", 0, 49),
      kv.lrange("flagged_conversations", 0, 49),
      kv.smembers("banned_ips"),
      kv.smembers("banned_ranges"),
      kv.smembers("banned_fingerprints"),
      kv.lrange("injection_attempts", 0, 49),
      kv.lrange("tyler_ai_call_requests", 0, 99),
      kv.lrange("visitor_intake_log", 0, 99),
      kv.hgetall("a11y_issues"),
      kv.hgetall("greet_links")
    ]);

    const greetLinks = Object.values(rawGreetLinks || {})
      .map((value) => {
        try {
          return typeof value === "string" ? JSON.parse(value) : value;
        } catch {
          return null;
        }
      })
      .filter(Boolean)
      .sort((a, b) => new Date(b.created) - new Date(a.created));

    const a11yIssues = Object.entries(rawA11yIssues || {})
      .map(([signature, value]) => {
        try {
          const record = typeof value === "string" ? JSON.parse(value) : value;
          return { signature, ...record };
        } catch {
          return null;
        }
      })
      .filter(Boolean)
      .sort((a, b) => new Date(b.lastSeen) - new Date(a.lastSeen));

    // What each role may SEE is decided here, not in the browser.
    //   READ_ONLY  : maintenance log, accessibility queue, status
    //   RESTRICTED : + visitor conversations, requests, intake, personal links
    //   ADMIN      : + security (injection attempts, bans) and everything else
    const rank = ROLE_RANK[req._role] || 0;
    const canVisitors = rank >= ROLE_RANK.RESTRICTED;
    const isAdmin = rank >= ROLE_RANK.ADMIN;
    return res.status(200).json({
      success: true,
      me: { role: req._role, who: req._who || "" },
      conversations: canVisitors ? parseEntries(rawConversations) : [],
      resumeRequests: canVisitors ? parseEntries(rawResumeRequests) : [],
      maintenanceLog: parseEntries(rawMaintenanceLog),
      flaggedConversations: canVisitors ? parseEntries(rawFlagged) : [],
      bannedIps: isAdmin ? (bannedIps || []) : [],
      bannedRanges: isAdmin ? (bannedRanges || []) : [],
      bannedFingerprints: isAdmin ? (bannedFingerprints || []) : [],
      injectionAttempts: isAdmin ? parseEntries(rawInjectionAttempts) : [],
      callRequests: canVisitors ? parseEntries(rawCallRequests) : [],
      intakeLog: canVisitors ? parseEntries(rawIntakeLog) : [],
      a11yIssues,
      greetLinks: canVisitors ? greetLinks : []
    });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ success: false, error: "Server error." });
  }
}

// Sections that support "Remove All". Each entry says how that section is stored.
const CLEARABLE = {
  conversation: { kind: "list", key: "tyler_ai_conversations" },
  resume: { kind: "list", key: "tyler_ai_resume_requests" },
  callRequest: { kind: "list", key: "tyler_ai_call_requests" },
  intake: { kind: "list", key: "visitor_intake_log" },
  injection: { kind: "list", key: "injection_attempts" },
  flagged: { kind: "list", key: "flagged_conversations" },
  maintenanceLog: { kind: "list", key: "site_maintenance_log" },
  bannedIp: { kind: "ipset", key: "banned_ips" },
  bannedRange: { kind: "set", key: "banned_ranges" },
  bannedFingerprint: { kind: "set", key: "banned_fingerprints" },
  a11y: { kind: "hash", key: "a11y_issues" },
  greet: { kind: "hash", key: "greet_links" }
};

async function handleClearAll(req, res) {
  if (!(await requireSession(req, res, "ADMIN"))) return;
  try {
    const type = req.body?.type;
    const spec = Object.prototype.hasOwnProperty.call(CLEARABLE, type) ? CLEARABLE[type] : null;
    if (!spec) return res.status(400).json({ error: "Invalid request." });

    if (spec.kind === "ipset") {
      // Unbanning also clears each address's strike count (same as a single unban).
      const ips = (await kv.smembers(spec.key)) || [];
      for (const ip of ips) await kv.del(`ip_strikes_${ip}`);
    }
    await kv.del(spec.key);
    return res.status(200).json({ success: true });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ success: false, error: "Server error." });
  }
}

async function handleDelete(req, res) {
  if (!(await requireSession(req, res, "ADMIN"))) return;

  try {
    const { type, index } = req.body;
    const key = KEYS[type];

    if (!key || typeof index !== "number") {
      return res.status(400).json({ error: "Invalid delete request." });
    }

    const rawEntries = await kv.lrange(key, 0, -1);

    if (!Array.isArray(rawEntries) || index < 0 || index >= rawEntries.length) {
      return res.status(400).json({ error: "Entry not found." });
    }

    const remaining = rawEntries.filter((_, i) => i !== index);

    await kv.del(key);

    for (const entry of remaining.slice().reverse()) {
      await kv.lpush(key, entry);
    }

    return res.status(200).json({ success: true });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ success: false, error: "Server error." });
  }
}

async function handleBanIp(req, res) {
  if (!(await requireSession(req, res, "ADMIN"))) return;

  try {
    const { ip, reason } = req.body;

    if (!ip || typeof ip !== "string") {
      return res.status(400).json({ error: "No IP address provided." });
    }

    await kv.sadd("banned_ips", ip);
    await kv.del(`ip_cooldown_${ip}`);

    await kv.lpush(
      "ip_ban_log",
      JSON.stringify({
        id: crypto.randomUUID(),
        ip,
        reason: reason || "Manually banned from dashboard",
        timestamp: new Date().toISOString()
      })
    );

    return res.status(200).json({ success: true });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ success: false, error: "Server error." });
  }
}

function getSlash24(ip) {
  const parts = ip.split(".");
  if (parts.length !== 4) return null;
  return `${parts[0]}.${parts[1]}.${parts[2]}.0/24`;
}

async function handleBanRange(req, res) {
  if (!(await requireSession(req, res, "ADMIN"))) return;

  try {
    const { ip, reason } = req.body;

    if (!ip || typeof ip !== "string") {
      return res.status(400).json({ error: "No IP address provided." });
    }

    const range = getSlash24(ip);

    if (!range) {
      return res.status(400).json({ error: "Could not determine a subnet for that IP." });
    }

    await kv.sadd("banned_ranges", range);

    await kv.lpush(
      "ip_ban_log",
      JSON.stringify({
        id: crypto.randomUUID(),
        ip: range,
        reason: reason || `Subnet ban from dashboard (based on ${ip})`,
        timestamp: new Date().toISOString()
      })
    );

    return res.status(200).json({ success: true, range });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ success: false, error: "Server error." });
  }
}

async function handleUnbanRange(req, res) {
  if (!(await requireSession(req, res, "ADMIN"))) return;

  try {
    const { range } = req.body;

    if (!range || typeof range !== "string") {
      return res.status(400).json({ error: "No range provided." });
    }

    await kv.srem("banned_ranges", range);

    return res.status(200).json({ success: true });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ success: false, error: "Server error." });
  }
}

